# writes src/09-cities.js: the world's towns and cities from Natural Earth's populated places (1:10m, 7,340 of them; public domain), for
# naming the place a finger taps on the Earth ("near Boston") and for finding a town by its name (the Earth's own menu, 18 Nov).
# usage: python3 -I tools/gen_cities.py <ne_10m_populated_places_simple.geojson>
# (from raw.githubusercontent.com/nvkelso/natural-earth-vector/master/geojson/; until 18 Nov the 1:50m file, 1,251 places, without
#  Providence)
import json, math, sys, collections
d = json.load(open(sys.argv[1], encoding='utf-8'))
SHORT = {'United States of America': 'United States', 'United Republic of Tanzania': 'Tanzania', 'Democratic Republic of the Congo': 'DR Congo',
         'Republic of the Congo': 'Congo', 'Central African Republic': 'Central African Rep.', 'Bosnia and Herzegovina': 'Bosnia',
         'United Arab Emirates': 'UAE', 'Dominican Republic': 'Dominican Rep.', 'Russian Federation': 'Russia', 'Czechia': 'Czechia'}
P = []
for f in d['features']:
    p = f['properties']; n = (p.get('name') or '').strip(); c = (p.get('adm0name') or '').strip(); a = (p.get('adm1name') or '').strip()
    if not n or '|' in n or '|' in c or '|' in a: continue
    c = SHORT.get(c, c); pop = p.get('pop_max') or 0
    # how big, 0 to 9: two steps a tenfold (1,000 is 0, 100,000 is 4, ten million is 8), the bigger first when a name is looked for
    r = max(0, min(9, int(math.log10(max(pop, 1)) * 2) - 6))
    P.append([n, c, a, p['latitude'], p['longitude'], r])
# the province or state only where a country has two of the name (Portland, Maine and Portland, Oregon)
twice = collections.Counter((x[0], x[1]) for x in P)
rows = ['%s|%s|%.2f|%.2f|%d%s' % (n, c, la, lo, r, ('|' + a) if twice[(n, c)] > 1 and a else '') for n, c, a, la, lo, r in P]
js = ('/* ---------- the world\'s towns and cities (Natural Earth, populated places at 1:10 million; public domain): the nearest names the place\n'
      '   a finger taps on the Earth, and a town found by its name. Generated by tools/gen_cities.py ---------- */\n'
      'var CITIES=(function(){var L=' + json.dumps('\n'.join(rows), ensure_ascii=False) + '.split("\\n").map(function(r){var a=r.split("|");return {n:a[0],c:a[1],la:+a[2],lo:+a[3],r:+a[4]||0,a:a[5]||\'\'}});\n'
      '  /* the nearest, and how far (km), along the Earth */\n'
      '  function near(lat,lon){var b=null,bd=1e9,c1=Math.cos(lat*Math.PI/180);for(var i=0;i<L.length;i++){var p=L[i],dy=p.la-lat,dx=((p.lo-lon+540)%360-180)*c1,d=dx*dx+dy*dy;if(d<bd){bd=d;b=p}}\n'
      '    if(!b)return null;var r=Math.PI/180,s=Math.sin((b.la-lat)*r/2),t=Math.sin((b.lo-lon)*r/2),h=s*s+Math.cos(lat*r)*Math.cos(b.la*r)*t*t;return {name:b.n,country:b.c,km:2*6371*Math.asin(Math.min(1,Math.sqrt(h)))}}\n'
      '  /* (18 Nov) a town by its name: those it begins with first, then those with a word that begins with it; the bigger first. Accents\n'
      '     and capitals do not matter ("sao paulo" finds São Paulo) */\n'
      '  var NK=null;function nk(s){s=String(s||\'\');try{s=s.normalize(\'NFD\').replace(/[\\u0300-\\u036f]/g,\'\')}catch(e){}return s.toLowerCase().replace(/[^a-z0-9]+/g,\' \').trim()}\n'
      '  function find(q,k){q=nk(q);if(!q)return [];if(!NK)NK=L.map(function(p){return nk(p.n)});var a=[],b=[],i;\n'
      '    for(i=0;i<L.length;i++){var s=NK[i];if(s.indexOf(q)===0)a.push(i);else if(q.length>1&&s.indexOf(\' \'+q)>=0)b.push(i)}\n'
      '    var by=function(x,y){return L[y].r-L[x].r||(L[x].n<L[y].n?-1:1)};a.sort(by);b.sort(by);\n'
      '    return a.concat(b).slice(0,k||6).map(function(i){var p=L[i];return {name:p.n,country:p.c,area:p.a,lat:p.la,lon:p.lo}})}\n'
      '  return {near:near,find:find,n:L.length}})();\n')
open('src/09-cities.js', 'w', encoding='utf-8').write(js)
print('cities', len(rows), len(js), 'bytes')
